import binascii
import io
import gzip

def task_func(compressed_hex):
    """
    Decode a hexadecimal string containing gzip-compressed data,
    decompress it, and return the UTF-8 decoded result.

    Args:
        compressed_hex: Hexadecimal string (or bytes) representing gzip data.

    Returns:
        str: Decoded UTF-8 text, or an error message if decoding fails.
    """
    try:
        if compressed_hex is None:
            return "Error: input is None"

        if isinstance(compressed_hex, bytes):
            compressed_hex = compressed_hex.decode("ascii", errors="strict")
        elif not isinstance(compressed_hex, str):
            compressed_hex = str(compressed_hex)

        hex_text = "".join(compressed_hex.split())
        if not hex_text:
            return "Error: input is empty"

        try:
            compressed_bytes = binascii.unhexlify(hex_text)
        except (binascii.Error, ValueError) as e:
            return f"Error: invalid hexadecimal input ({e})"

        try:
            decompressed_bytes = gzip.decompress(compressed_bytes)
        except (OSError, EOFError, gzip.BadGzipFile) as e:
            return f"Error: gzip decompression failed ({e})"

        try:
            decoded_string = decompressed_bytes.decode("utf-8")
        except UnicodeDecodeError as e:
            return f"Error: UTF-8 decoding failed ({e})"

        return decoded_string

    except Exception as e:
        return f"Error: unexpected failure ({e})"

