import urllib.request
from lxml import etree
import pandas as pd


def task_func(url):
    def local_name(node):
        return etree.QName(node).localname

    try:
        with urllib.request.urlopen(url) as response:
            xml_data = response.read()
    except Exception as exc:
        raise ValueError("Unable to fetch XML from URL.") from exc

    try:
        root = etree.fromstring(xml_data)
    except Exception as exc:
        raise ValueError("Unable to parse XML from URL.") from exc

    items = [
        elem
        for elem in root.iter()
        if isinstance(elem.tag, str) and local_name(elem) == "item"
    ]

    if not items:
        raise ValueError("XML structure does not match expected format.")

    rows = []
    for item in items:
        if item.attrib:
            # Attributes are not part of the expected item-to-columns structure.
            pass

        if (item.text or "").strip():
            raise ValueError("XML structure does not match expected format.")

        row = {}
        seen_columns = set()

        for child in item:
            if not isinstance(child.tag, str):
                continue

            col_name = local_name(child)

            if col_name in seen_columns:
                raise ValueError("XML structure does not match expected format.")
            seen_columns.add(col_name)

            if any(isinstance(grandchild.tag, str) for grandchild in child):
                raise ValueError("XML structure does not match expected format.")

            if (child.tail or "").strip():
                raise ValueError("XML structure does not match expected format.")

            value = child.text.strip() if child.text is not None else None
            if value == "":
                value = None

            row[col_name] = value

        if not row:
            raise ValueError("XML structure does not match expected format.")

        rows.append(row)

    return pd.DataFrame(rows)

