import pandas as pd
import numpy as np
from scipy.stats import chi2_contingency


def task_func(data, col1, col2):
    if not isinstance(data, pd.DataFrame) or data.empty:
        raise ValueError("data must be a non-empty DataFrame")

    if col1 not in data.columns or col2 not in data.columns:
        raise ValueError("col1 and col2 must be present in data")

    subset = data[[col1, col2]].dropna()
    if subset.empty:
        raise ValueError("data must contain at least one valid observation")

    def _is_categorical_series(series):
        dtype = series.dtype
        return (
            pd.api.types.is_categorical_dtype(dtype)
            or pd.api.types.is_object_dtype(dtype)
            or pd.api.types.is_string_dtype(dtype)
            or pd.api.types.is_bool_dtype(dtype)
        )

    for col in (col1, col2):
        if not _is_categorical_series(subset[col]):
            raise TypeError("one or both columns contain non-categorical data")

        unique_count = subset[col].nunique(dropna=True)
        if unique_count < 2:
            raise ValueError("one or both columns do not have multiple categories")

        counts = subset[col].value_counts(dropna=True)
        if (counts < 5).any():
            raise ValueError("some categories have less than 5 observations")

    contingency_table = pd.crosstab(subset[col1], subset[col2])

    if contingency_table.empty or contingency_table.shape[0] < 2 or contingency_table.shape[1] < 2:
        raise ValueError("one or both columns do not have multiple categories")

    _, p_value, _, expected = chi2_contingency(contingency_table)

    if (expected < 5).any():
        raise ValueError("chi-square test assumptions are violated")

    return float(p_value)

